output_text:
[
  {
    "id": "borrowed_cart_must_be_returned",
    "text": "Any shopper who takes a cart is obliged to return it to the register cart-return point before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "at_register_return": "at(0,1)",
        "cart_parked_at_register": "cartAt(0,1)"
      },
      "events": {
        "borrow_cart": {
          "pre": "PICKUP_CART",
          "post": "hasCart"
        },
        "return_cart_to_register": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_register_return"
            ]
          },
          "post": "cart_parked_at_register"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "borrow_cart",
      "discharge": "return_cart_to_register"
    }
  },
  {
    "id": "only_leave_cart_at_register",
    "text": "Carts may only be left at the designated register return cell.",
    "abstraction": {
      "state_properties": {
        "at_register_return": "at(0,1)"
      },
      "events": {
        "leave_cart_away_from_register": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "at_register_return"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_away_from_register"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "A shopper is forbidden from exiting the store while still pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "possessing_cart": "hasCart",
        "at_exit": "at(9,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "possessing_cart"
        ]
      }
    }
  },
  {
    "id": "no_carts_in_exit_corridor",
    "text": "Store carts are forbidden in the lower exit corridor leading to the store exit.",
    "abstraction": {
      "state_properties": {
        "possessing_cart": "hasCart",
        "in_exit_corridor": {
          "or": [
            "at(2,5)",
            "at(3,5)",
            "at(4,5)",
            "at(5,5)",
            "at(6,5)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "possessing_cart",
          "in_exit_corridor"
        ]
      }
    }
  },
  {
    "id": "items_must_be_taken_with_cart",
    "text": "A shopper is forbidden from picking up shelf items unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "possessing_cart": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "pickup_item_without_cart": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "without_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_item_without_cart"
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "Customers are forbidden from carrying merchandise by hand rather than placing it in a cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "cartless_hand_carry": {
          "and": [
            "handFull",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "cart_item_requires_checkout_dropoff",
    "text": "After collecting any item while using a cart, the shopper is obliged to check out by leaving the cart at the register return.",
    "abstraction": {
      "state_properties": {
        "at_register_return": "at(0,1)",
        "cart_parked_at_register": "cartAt(0,1)"
      },
      "events": {
        "cart_item_collected": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "checkout_by_cart_dropoff": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "at_register_return"
            ]
          },
          "post": "cart_parked_at_register"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cart_item_collected",
      "discharge": "checkout_by_cart_dropoff"
    }
  },
  {
    "id": "exit_only_after_cart_parked",
    "text": "A shopper is forbidden from exiting unless the store cart has already been parked at the register return.",
    "abstraction": {
      "state_properties": {
        "cart_parked_at_register": "cartAt(0,1)",
        "cart_not_parked_at_register": {
          "not": "cartAt(0,1)"
        },
        "at_exit": "at(9,5)"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "cart_not_parked_at_register"
        ]
      }
    }
  }
]
